command:
// ==========================================
// LUNAS WIRKUNG: ANKER IM DIESSEITS (ZERZAL)
//
// - genau ein Geist
// - genau ein Erwachter als Anker
// - Wirkender darf selbst der Anker sein
// - Reichweite 16 Schritt
// - Spieler erzeugt Karte und GM-Anfrage
// - eine gemeinsame Karte über Block 19.8
// - beide Effekte direkt über Block 5
// - sichtbare Symbole automatisch durch Block 5
// - nur vollständige Bindung
// ==========================================

(async function () {
    const macroUuid = this?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const pruefeFramework = () => {
    const fw = globalThis.DSK, fehlt = [];
    const pruefungen = {
        "Effekt.Anwenden": fw?.Effekt?.Anwenden,
        "Effekt.CheckTarget": fw?.Effekt?.CheckTarget,
        "EffektEnde.Register": fw?.EffektEnde?.Register,
        "QS.Ermitteln": fw?.QS?.Ermitteln,
        "Token.Finde": fw?.Token?.Finde,
        "Target.Merken": fw?.Target?.Merken,
        "Target.Finden": fw?.Target?.Finden,
        "Target.Actor": fw?.Target?.Actor,
        "Geometrie.Distanz": fw?.Geometrie?.Distanz,
        "Empfaenger.GMUndBesitzer": fw?.Empfaenger?.GMUndBesitzer,
        "GMAnfrage.Speichern": fw?.GMAnfrage?.Speichern,
        "GMAnfrage.Finden": fw?.GMAnfrage?.Finden,
        "GMAnfrage.Lesen": fw?.GMAnfrage?.Lesen,
        "GMAnfrage.Loeschen": fw?.GMAnfrage?.Loeschen,
        "GabenUI.GMMakroButton": fw?.GabenUI?.GMMakroButton,
        "GabenUI.AnfrageKarteErstellen": fw?.GabenUI?.AnfrageKarteErstellen,
        "GabenUI.AnfrageKarteAktualisieren": fw?.GabenUI?.AnfrageKarteAktualisieren
    };
    for (const [name, funktion] of Object.entries(pruefungen)) {
        if (typeof funktion !== "function") fehlt.push(name);
    }
    return fehlt;
};

if (pruefeFramework().length) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
}

const DSK_FW = globalThis.DSK;
const fehlend = pruefeFramework();

console.log("ANKER FRAMEWORK-PRÜFUNG", {
    version: DSK_FW?.version,
    fehlend,
    vollständig: fehlend.length === 0
});

if (fehlend.length) {
    return ui.notifications.error(
        `Luna sagt 🌙: Anker-Prüfung fehlgeschlagen: ${fehlend.join(", ")}`
    );
}

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Anker im Diesseits", vollerName = "Anker im Diesseits (Zerzal)", ahne = "Zerzal";
    const maxReichweite = 16, flagKey = "pendingAnkerImDiesseitsZerzal";

    DSK_FW.EffektEnde.Register("ankerImDiesseits", vollerName, "Die unnatürliche Bindung bricht zusammen.");

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const istAktiverGM = () => {
        const aktiverGM = game.users.find(user => user.isGM && user.active);
        return aktiverGM ? game.user.isGM && game.user.id === aktiverGM.id : game.user.isGM;
    };

    const ladeGespeichertenActor = async daten => {
        if (!daten) return null;
        const token = await DSK_FW.Target.Finden(daten);
        return token?.actor || await DSK_FW.Target.Actor(daten);
    };

    const findeBindung = (actor, bindungsId, rolle) =>
        actor?.effects?.find(effect =>
            (effect.name || effect.label || "") === vollerName &&
            effect.getFlag("dsk", "ankerImDiesseits") === true &&
            effect.getFlag("dsk", "bindungsId") === bindungsId &&
            effect.getFlag("dsk", "rolle") === rolle
        ) || null;

    const loescheEffekt = async effect => {
        if (!effect) return false;
        try { await effect.delete(); return true; }
        catch (error) {
            console.error("Anker im Diesseits: Effekt konnte nicht gelöscht werden.", { effect, error });
            return false;
        }
    };

    // +++ 4 - GEKOPPELTE EFFEKTE ÜBER BLOCK 5 +++++++++++++++++

    const wendeBindungAn = async ({ casterActor, casterName, geistActor, geistName, ankerActor, ankerName, qs, bindungsId }) => {
        if (!casterActor || !geistActor || !ankerActor) return false;

        const dauer = { seconds: qs * 60, startTime: game.time.worldTime };
        const grundBeschreibung =
            `Ein Geist wird an einen vom Zerzalkind bestimmten Erwachten gebunden und ins Diesseits gezwungen.` +
            `<br><br>Der Geist materialisiert auch ohne die Fähigkeit Materialisierung.` +
            `<br><br>Der Geist bleibt materialisiert, solange der Anker sich im Umkreis von 8 Schritt befindet, ` +
            `lebt und bei Bewusstsein ist. Andernfalls kommt der Geist wieder frei und verliert seinen verletzlichen weltlichen Körper.` +
            `<br><br><b>Wirkungsdauer:</b> ${qs} Minuten`;

        const alteGeistEffekte = geistActor.effects.filter(effect =>
            (effect.name || effect.label || "") === vollerName && effect.getFlag("dsk", "ankerImDiesseits") === true
        );
        const alteAnkerEffekte = ankerActor.effects.filter(effect =>
            (effect.name || effect.label || "") === vollerName && effect.getFlag("dsk", "ankerImDiesseits") === true
        );

        for (const effect of [...alteGeistEffekte, ...alteAnkerEffekte]) await loescheEffekt(effect);

        let geistEffekt = null, ankerEffekt = null;

        try {
            geistEffekt = await DSK_FW.Effekt.Anwenden({
                name: vollerName, ahne,
                beschreibung: grundBeschreibung + `<br><hr><b>Rolle:</b> Materialisierter Geist` + `<br><b>Gebunden an:</b> ${ankerName}` + `<br><b>Gabe gewirkt von:</b> ${casterName}`,
                gabeZiel: "geist", qs, ziel: geistActor, duration: dauer,
                flags: { dsk: {
                    ankerImDiesseits: true, casterUuid: casterActor.uuid, casterName, bindungsId, rolle: "geist",
                    geistUuid: geistActor.uuid, geistName, ankerUuid: ankerActor.uuid, ankerName, partnerUuid: ankerActor.uuid, qs
                }}
            });

            if (!geistEffekt) throw new Error("Der Effekt auf dem Geist konnte nicht erstellt werden.");

            ankerEffekt = await DSK_FW.Effekt.Anwenden({
                name: vollerName, ahne,
                beschreibung: grundBeschreibung + `<br><hr><b>Rolle:</b> Anker im Diesseits` + `<br><b>Gebundener Geist:</b> ${geistName}` + `<br><b>Gabe gewirkt von:</b> ${casterName}`,
                gabeZiel: "erwachte", qs, ziel: ankerActor, duration: dauer,
                flags: { dsk: {
                    ankerImDiesseits: true, casterUuid: casterActor.uuid, casterName, bindungsId, rolle: "anker",
                    geistUuid: geistActor.uuid, geistName, ankerUuid: ankerActor.uuid, ankerName, partnerUuid: geistActor.uuid, qs
                }}
            });

            if (!ankerEffekt) throw new Error("Der Effekt auf dem Anker konnte nicht erstellt werden.");

            const geistErfolgreich =
                (geistEffekt.name || geistEffekt.label || "") === vollerName &&
                geistEffekt.getFlag("dsk", "ankerImDiesseits") === true &&
                geistEffekt.getFlag("dsk", "bindungsId") === bindungsId &&
                geistEffekt.getFlag("dsk", "rolle") === "geist";

            const ankerErfolgreich =
                (ankerEffekt.name || ankerEffekt.label || "") === vollerName &&
                ankerEffekt.getFlag("dsk", "ankerImDiesseits") === true &&
                ankerEffekt.getFlag("dsk", "bindungsId") === bindungsId &&
                ankerEffekt.getFlag("dsk", "rolle") === "anker";

            if (!geistErfolgreich || !ankerErfolgreich) throw new Error("Die Bindung zwischen Geist und Anker ist unvollständig.");
            return true;

        } catch (error) {
            console.error("Anker im Diesseits: Effektanlage fehlgeschlagen.", error);
            if (ankerEffekt) await loescheEffekt(ankerEffekt);
            if (geistEffekt) await loescheEffekt(geistEffekt);
            return false;
        }
    };

    // +++ 5 - GM-ANFRAGE VERARBEITEN ++++++++++++++++++++++++++

    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!casterActor || !daten || !istAktiverGM()) return false;

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
        const geistActor = await ladeGespeichertenActor(daten.geist);
        const ankerActor = await ladeGespeichertenActor(daten.anker);

        if (!casterToken) {
            ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
            return false;
        }
        if (!geistActor || !ankerActor) {
            ui.notifications.warn("Luna sagt 🌙: Geist oder Anker wurde nicht gefunden!");
            return false;
        }
        if (!DSK_FW.Effekt.CheckTarget(geistActor, "geist")) {
            ui.notifications.warn("Luna sagt 🌙: Das gespeicherte Geistziel ist kein Geist!");
            return false;
        }
        if (!DSK_FW.Effekt.CheckTarget(ankerActor, "erwachte")) {
            ui.notifications.warn("Luna sagt 🌙: Der gespeicherte Anker ist kein Erwachter!");
            return false;
        }

        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
        const geistName = daten.geist?.name || DSK_FW.ResolveTokenName(geistActor);
        const ankerName = daten.anker?.name || DSK_FW.ResolveTokenName(ankerActor);
        const bindungsId = daten.bindungsId || `anker-${Date.now()}-${foundry.utils.randomID()}`;

        const erfolgreich = await wendeBindungAn({
            casterActor, casterName, geistActor, geistName, ankerActor, ankerName, qs, bindungsId
        });

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId, gabenName: vollerName, ahne, beschreibung: daten.beschreibung || "", wirkender: casterName,
            ziele: [
                { name: geistName, rolle: "Materialisierter Geist" },
                { name: ankerName, rolle: "Anker im Diesseits" }
            ],
            misserfolge: erfolgreich ? [] : [{ name: `${geistName} und ${ankerName}`, rolle: "Bindung" }],
            dauerText: `${qs} Minuten`, erfolgreich
        });

        if (!erfolgreich) {
            ui.notifications.error("Luna sagt 🌙: Die Bindung konnte nicht vollständig hergestellt werden!");
            return false;
        }

        ui.notifications.info(`Luna sagt 🌙: ${geistName} wurde an ${ankerName} gebunden.`);
        return true;
    };

    // +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;
                if (await verarbeiteAnfrage(anfrageActor, daten)) await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
            }
            return;
        }
    }

    // +++ 7 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor).find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) || null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
    if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!");

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor, gabenName, suchbegriffe: ["Anker im Diesseits Probe", "Anker im Diesseits"],
        testDataObj: typeof testData !== "undefined" ? testData : null, fallback: 0, protokollieren: true
    });

    if (qs <= 0) return ui.notifications.warn("Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!");

    // +++ 8 - TARGETS AUSWERTEN +++++++++++++++++++++++++++++++

    const targets = Array.from(game.user.targets);
    if (!targets.length) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle mindestens den Geist als Target aus!");

    const geister = targets.filter(token => token?.actor && DSK_FW.Effekt.CheckTarget(token.actor, "geist"));
    const erwachte = targets.filter(token => token?.actor && DSK_FW.Effekt.CheckTarget(token.actor, "erwachte"));
    let geistZiel = null, ankerZiel = null;

    if (targets.length === 1 && geister.length === 1) {
        geistZiel = geister[0];
        ankerZiel = casterToken;
    } else if (targets.length === 2 && geister.length === 1 && erwachte.length === 1) {
        geistZiel = geister[0];
        ankerZiel = erwachte[0];
    } else {
        return ui.notifications.warn("Luna sagt 🌙: Wähle genau einen Geist und optional genau einen Erwachten als Anker aus!");
    }

    if (!geistZiel?.actor || !ankerZiel?.actor) return ui.notifications.warn("Luna sagt 🌙: Geist oder Anker besitzt keinen gültigen Charakterbogen!");

    // +++ 9 - REICHWEITE +++++++++++++++++++++++++++++++++++++++

    const fehlschlaege = [];
    const distanzGeist = DSK_FW.Geometrie.Distanz(casterToken, geistZiel);
    const distanzAnker = DSK_FW.Geometrie.Distanz(casterToken, ankerZiel);

    if (distanzGeist > maxReichweite) {
        fehlschlaege.push({ name: geistZiel.name, grund: `${Math.ceil(distanzGeist - maxReichweite)} Schritt zu weit entfernt` });
    }

    if (ankerZiel.id !== casterToken.id && distanzAnker > maxReichweite) {
        fehlschlaege.push({ name: ankerZiel.name, grund: `${Math.ceil(distanzAnker - maxReichweite)} Schritt zu weit entfernt` });
    }

    if (fehlschlaege.length) {
        await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: DSK_FW.Empfaenger.GMUndBesitzer(casterActor, { anfragenderUserId: game.user.id }),
            content: `
                ${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="text-align:center;color:#B30000;font-weight:bold;">Fehlschlag</p>
                    ${DSK_FW.UI.List(fehlschlaege.map(eintrag => `${eintrag.name} – ${eintrag.grund}`))}
                    <hr>
                    <p style="text-align:center;margin-bottom:0;"><b>Kontrolliere deine Target-Auswahl.</b><br>
                    Wirke die Gabe erneut, wenn es der GM erlaubt; ansonsten ist dies ein Fehlschlag.</p>
                </div>`
        });

        if (casterActor.getFlag("world", "letzteGabenQS") !== undefined) await casterActor.unsetFlag("world", "letzteGabenQS");
        return;
    }

    // +++ 10 - DATEN UND BESCHREIBUNG SPEICHERN +++++++++++++++

    const geistDaten = DSK_FW.Target.Merken(geistZiel), ankerDaten = DSK_FW.Target.Merken(ankerZiel);
    if (!geistDaten || !ankerDaten) return ui.notifications.warn("Luna sagt 🌙: Geist oder Anker konnte nicht gespeichert werden!");

    const geistName = geistDaten.name || DSK_FW.ResolveTokenName(geistZiel.actor);
    const ankerName = ankerDaten.name || DSK_FW.ResolveTokenName(ankerZiel.actor);
    const bindungsId = `anker-${Date.now()}-${foundry.utils.randomID()}`;

    const beschreibung =
        `Ein Geist wird an einen vom Zerzalkind bestimmten Erwachten gebunden und ins Diesseits gezwungen.` +
        `<br><br>Der Geist materialisiert auch ohne die Fähigkeit Materialisierung.` +
        `<br><br>Der Geist bleibt materialisiert, solange der Anker sich im Umkreis von 8 Schritt befindet, ` +
        `lebt und bei Bewusstsein ist. Andernfalls kommt der Geist wieder frei und verliert seinen verletzlichen weltlichen Körper.` +
        `<br><br><b>Zielkategorie:</b> ein Geist und ein Erwachter` +
        `<br><b>Reichweite beim Wirken:</b> ${maxReichweite} Schritt`;

    // +++ 11 - GEMEINSAME KARTE ++++++++++++++++++++++++++++++++

    const gmLink = DSK_FW.GabenUI.GMMakroButton(macroUuid);

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
        ziele: [
            { name: geistName, rolle: "Materialisierter Geist" },
            { name: ankerName, rolle: "Anker im Diesseits" }
        ],
        dauerText: `${qs} Minuten`, gmLink, gmBereich: !game.user.isGM, anfragenderUserId: game.user.id
    });

    if (!nachricht) return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");

    const anfrageDaten = {
        casterUuid: casterActor.uuid, casterName,
        casterTokenId: casterToken.id, casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
        geist: geistDaten, anker: ankerDaten, qs, bindungsId, beschreibung,
        sceneId: canvas.scene?.id || null, requestedByUserId: game.user.id, messageId: nachricht.id, macroUuid
    };

    // +++ 12 - GM DIREKT ODER ANFRAGE SPEICHERN +++++++++++++++

    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        if (casterActor.getFlag("world", "letzteGabenQS") !== undefined) await casterActor.unsetFlag("world", "letzteGabenQS");
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);

    // +++ 13 - QS AUFRÄUMEN ++++++++++++++++++++++++++++++++++++

    if (casterActor.getFlag("world", "letzteGabenQS") !== undefined) await casterActor.unsetFlag("world", "letzteGabenQS");
    ui.notifications.info("Luna sagt 🌙: Die Bindung wurde bei der Spielleitung beantragt.");

}).call(this);
